import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry layernorm_affine(
    .param .u64 p_in,
    .param .u64 p_out,
    .param .u64 p_gamma,
    .param .u64 p_beta,
    .param .u32 p_norm,
    .param .u32 p_batch,
    .param .f32 p_eps
)
{
    .reg .pred   %p<6>;
    .reg .b32    %r<40>;
    .reg .b64    %rd<60>;
    .reg .f32    %f<60>;
    .reg .f64    %fd<40>;
     .shared .align 16 .f64 sh_sum[64];
     .shared .align 16 .f64 sh_sumsq[64];
    .shared .align 4  .f32 sh_mean;
    .shared .align 4  .f32 sh_invstd;
    // Load params
    ld.param.u64    %rd10, [p_in];
    ld.param.u64    %rd11, [p_out];
    ld.param.u64    %rd12, [p_gamma];
    ld.param.u64    %rd13, [p_beta];
    ld.param.u32    %r20,  [p_norm];
    ld.param.u32    %r21,  [p_batch];
    ld.param.f32    %f20,  [p_eps];
    // Thread/block info
    mov.u32         %r0, %tid.x;
    mov.u32         %r1, %ntid.x;
    mov.u32         %r2, %ctaid.x;
    // Compute base pointers for this sample
    mul.wide.u32    %rd25, %r2, %r20;      // elements
    mul.lo.u64      %rd26, %rd25, 4;       // bytes
    add.s64         %rd30, %rd10, %rd26;   // base_in = in + bytes
    add.s64         %rd31, %rd11, %rd26;   // base_out = out + bytes
    // Prepare shared memory base addresses
     mov.u64         %rd32, sh_sum;
     mov.u64         %rd33, sh_sumsq;
     mov.u64         %rd34, sh_mean;
     mov.u64         %rd35, sh_invstd;
    // Precompute tid*8 for shared indexing (double arrays)
    mul.wide.u32    %rd24, %r0, 8;
    // Single-pass accumulation: compute sum and sumsq together
    // ------------------------------------------------------------
    mov.f32         %f0, 0f00000000;       // acc_sum (f32, unused)
    mov.f64         %fd0, 0d0000000000000000;       // acc_sum (f64) = 0.0
    mov.f64         %fd1, 0d0000000000000000;       // acc_sumsq (f64) = 0.0
    shr.u32         %r5, %r20, 2;              // N4 = N / 4
    mov.u32         %r3, %r0;                  // vec_idx = tid
L_vec_sum_sumsq:
    setp.ge.u32     %p0, %r3, %r5;
    @%p0 bra        L_done_vec_sum_sumsq;
    mul.wide.u32    %rd1, %r3, 16;             // byte offset = vec_idx * 16
    add.s64         %rd2, %rd30, %rd1;         // addr = base_in + off
    ld.global.v4.f32 {%f2,%f3,%f4,%f5}, [%rd2];
    // accumulate sum (f64)
    cvt.f64.f32     %fd2, %f2;
    cvt.f64.f32     %fd3, %f3;
    cvt.f64.f32     %fd4, %f4;
    cvt.f64.f32     %fd5, %f5;
    add.f64         %fd0, %fd0, %fd2;
    add.f64         %fd0, %fd0, %fd3;
    add.f64         %fd0, %fd0, %fd4;
    add.f64         %fd0, %fd0, %fd5;
    // accumulate sum of squares (f64)
    fma.rn.f64      %fd1, %fd2, %fd2, %fd1;
    fma.rn.f64      %fd1, %fd3, %fd3, %fd1;
    fma.rn.f64      %fd1, %fd4, %fd4, %fd1;
    fma.rn.f64      %fd1, %fd5, %fd5, %fd1;
    add.u32         %r3, %r3, %r1;            // advance by blockDim.x
    bra             L_vec_sum_sumsq;
L_done_vec_sum_sumsq:
    // Scalar tail for remaining N % 4 elements
    shl.b32         %r6, %r5, 2;               // base_scalar = N4 * 4
    add.u32         %r3, %r0, %r6;             // idx = tid + base_scalar
L_tail_sum_sumsq:
    setp.ge.u32     %p0, %r3, %r20;
    @%p0 bra        L_done_tail_sum_sumsq;
    mul.wide.u32    %rd1, %r3, 4;
    add.s64         %rd2, %rd30, %rd1;
    ld.global.f32   %f2, [%rd2];
    add.f32         %f0, %f0, %f2;
    cvt.f64.f32     %fd2, %f2;
    add.f64         %fd0, %fd0, %fd2;
    fma.rn.f64      %fd1, %fd2, %fd2, %fd1;
    add.u32         %r3, %r3, %r1;
    bra             L_tail_sum_sumsq;
L_done_tail_sum_sumsq:
    // Warp-level reduction of f64 sum and sumsq, then inter-warp reduction
    // Compute lane and warp id
    and.b32         %r22, %r0, 31;        // lane = tid & 31
    shr.u32         %r23, %r0, 5;         // warp_id = tid >> 5
    // Intra-warp reduce: sum (fd0) and sumsq (fd1)
    // offset 16
    mov.b64         %rd40, %fd0;
    cvt.u32.u64     %r24, %rd40;
    shr.u64         %rd41, %rd40, 32;
    cvt.u32.u64     %r25, %rd41;
     shfl.sync.down.b32  %r26, %r24, 16, 31, 0xffffffff;
     shfl.sync.down.b32  %r27, %r25, 16, 31, 0xffffffff;
    cvt.u64.u32     %rd42, %r26;
    cvt.u64.u32     %rd43, %r27;
    shl.b64         %rd43, %rd43, 32;
    or.b64          %rd42, %rd42, %rd43;
    mov.b64         %fd30, %rd42;
    add.f64         %fd0, %fd0, %fd30;
    mov.b64         %rd44, %fd1;
    cvt.u32.u64     %r28, %rd44;
    shr.u64         %rd45, %rd44, 32;
    cvt.u32.u64     %r29, %rd45;
     shfl.sync.down.b32  %r30, %r28, 16, 31, 0xffffffff;
     shfl.sync.down.b32  %r31, %r29, 16, 31, 0xffffffff;
    cvt.u64.u32     %rd46, %r30;
    cvt.u64.u32     %rd47, %r31;
    shl.b64         %rd47, %rd47, 32;
    or.b64          %rd46, %rd46, %rd47;
    mov.b64         %fd31, %rd46;
    add.f64         %fd1, %fd1, %fd31;
    // offset 8
    mov.b64         %rd40, %fd0;
    cvt.u32.u64     %r24, %rd40;
    shr.u64         %rd41, %rd40, 32;
    cvt.u32.u64     %r25, %rd41;
     shfl.sync.down.b32  %r26, %r24, 8, 31, 0xffffffff;
     shfl.sync.down.b32  %r27, %r25, 8, 31, 0xffffffff;
    cvt.u64.u32     %rd42, %r26;
    cvt.u64.u32     %rd43, %r27;
    shl.b64         %rd43, %rd43, 32;
    or.b64          %rd42, %rd42, %rd43;
    mov.b64         %fd30, %rd42;
    add.f64         %fd0, %fd0, %fd30;
    mov.b64         %rd44, %fd1;
    cvt.u32.u64     %r28, %rd44;
    shr.u64         %rd45, %rd44, 32;
    cvt.u32.u64     %r29, %rd45;
     shfl.sync.down.b32  %r30, %r28, 8, 31, 0xffffffff;
     shfl.sync.down.b32  %r31, %r29, 8, 31, 0xffffffff;
    cvt.u64.u32     %rd46, %r30;
    cvt.u64.u32     %rd47, %r31;
    shl.b64         %rd47, %rd47, 32;
    or.b64          %rd46, %rd46, %rd47;
    mov.b64         %fd31, %rd46;
    add.f64         %fd1, %fd1, %fd31;
    // offset 4
    mov.b64         %rd40, %fd0;
    cvt.u32.u64     %r24, %rd40;
    shr.u64         %rd41, %rd40, 32;
    cvt.u32.u64     %r25, %rd41;
     shfl.sync.down.b32  %r26, %r24, 4, 31, 0xffffffff;
     shfl.sync.down.b32  %r27, %r25, 4, 31, 0xffffffff;
    cvt.u64.u32     %rd42, %r26;
    cvt.u64.u32     %rd43, %r27;
    shl.b64         %rd43, %rd43, 32;
    or.b64          %rd42, %rd42, %rd43;
    mov.b64         %fd30, %rd42;
    add.f64         %fd0, %fd0, %fd30;
    mov.b64         %rd44, %fd1;
    cvt.u32.u64     %r28, %rd44;
    shr.u64         %rd45, %rd44, 32;
    cvt.u32.u64     %r29, %rd45;
     shfl.sync.down.b32  %r30, %r28, 4, 31, 0xffffffff;
     shfl.sync.down.b32  %r31, %r29, 4, 31, 0xffffffff;
    cvt.u64.u32     %rd46, %r30;
    cvt.u64.u32     %rd47, %r31;
    shl.b64         %rd47, %rd47, 32;
    or.b64          %rd46, %rd46, %rd47;
    mov.b64         %fd31, %rd46;
    add.f64         %fd1, %fd1, %fd31;
    // offset 2
    mov.b64         %rd40, %fd0;
    cvt.u32.u64     %r24, %rd40;
    shr.u64         %rd41, %rd40, 32;
    cvt.u32.u64     %r25, %rd41;
     shfl.sync.down.b32  %r26, %r24, 2, 31, 0xffffffff;
     shfl.sync.down.b32  %r27, %r25, 2, 31, 0xffffffff;
    cvt.u64.u32     %rd42, %r26;
    cvt.u64.u32     %rd43, %r27;
    shl.b64         %rd43, %rd43, 32;
    or.b64          %rd42, %rd42, %rd43;
    mov.b64         %fd30, %rd42;
    add.f64         %fd0, %fd0, %fd30;
    mov.b64         %rd44, %fd1;
    cvt.u32.u64     %r28, %rd44;
    shr.u64         %rd45, %rd44, 32;
    cvt.u32.u64     %r29, %rd45;
     shfl.sync.down.b32  %r30, %r28, 2, 31, 0xffffffff;
     shfl.sync.down.b32  %r31, %r29, 2, 31, 0xffffffff;
    cvt.u64.u32     %rd46, %r30;
    cvt.u64.u32     %rd47, %r31;
    shl.b64         %rd47, %rd47, 32;
    or.b64          %rd46, %rd46, %rd47;
    mov.b64         %fd31, %rd46;
    add.f64         %fd1, %fd1, %fd31;
    // offset 1
    mov.b64         %rd40, %fd0;
    cvt.u32.u64     %r24, %rd40;
    shr.u64         %rd41, %rd40, 32;
    cvt.u32.u64     %r25, %rd41;
     shfl.sync.down.b32  %r26, %r24, 1, 31, 0xffffffff;
     shfl.sync.down.b32  %r27, %r25, 1, 31, 0xffffffff;
    cvt.u64.u32     %rd42, %r26;
    cvt.u64.u32     %rd43, %r27;
    shl.b64         %rd43, %rd43, 32;
    or.b64          %rd42, %rd42, %rd43;
    mov.b64         %fd30, %rd42;
    add.f64         %fd0, %fd0, %fd30;
    mov.b64         %rd44, %fd1;
    cvt.u32.u64     %r28, %rd44;
    shr.u64         %rd45, %rd44, 32;
    cvt.u32.u64     %r29, %rd45;
     shfl.sync.down.b32  %r30, %r28, 1, 31, 0xffffffff;
     shfl.sync.down.b32  %r31, %r29, 1, 31, 0xffffffff;
    cvt.u64.u32     %rd46, %r30;
    cvt.u64.u32     %rd47, %r31;
    shl.b64         %rd47, %rd47, 32;
    or.b64          %rd46, %rd46, %rd47;
    mov.b64         %fd31, %rd46;
    add.f64         %fd1, %fd1, %fd31;
    // Write per-warp partials (lane 0 of each warp)
    setp.eq.u32     %p0, %r22, 0;
    @!%p0 bra       L_skip_store_warp;
        mul.wide.u32    %rd48, %r23, 8;
        add.s64         %rd49, %rd32, %rd48;
        st.shared.f64   [%rd49], %fd0;
        add.s64         %rd50, %rd33, %rd48;
        st.shared.f64   [%rd50], %fd1;
L_skip_store_warp:
    bar.sync 0;
    // Warp 0 reduces across warps and computes final stats
    setp.eq.u32     %p1, %r23, 0;
    @!%p1 bra       L_after_final_warp_reduce;
        mul.wide.u32    %rd51, %r22, 8;
        add.s64         %rd52, %rd32, %rd51;
        ld.shared.f64   %fd0, [%rd52];
        add.s64         %rd53, %rd33, %rd51;
        ld.shared.f64   %fd1, [%rd53];
        // Intra-warp reduction within warp 0
        // offset 16
        mov.b64         %rd40, %fd0;
        cvt.u32.u64     %r24, %rd40;
        shr.u64         %rd41, %rd40, 32;
        cvt.u32.u64     %r25, %rd41;
         shfl.sync.down.b32  %r26, %r24, 16, 31, 0xffffffff;
         shfl.sync.down.b32  %r27, %r25, 16, 31, 0xffffffff;
        cvt.u64.u32     %rd42, %r26;
        cvt.u64.u32     %rd43, %r27;
        shl.b64         %rd43, %rd43, 32;
        or.b64          %rd42, %rd42, %rd43;
        mov.b64         %fd30, %rd42;
        add.f64         %fd0, %fd0, %fd30;
        mov.b64         %rd44, %fd1;
        cvt.u32.u64     %r28, %rd44;
        shr.u64         %rd45, %rd44, 32;
        cvt.u32.u64     %r29, %rd45;
         shfl.sync.down.b32  %r30, %r28, 16, 31, 0xffffffff;
         shfl.sync.down.b32  %r31, %r29, 16, 31, 0xffffffff;
        cvt.u64.u32     %rd46, %r30;
        cvt.u64.u32     %rd47, %r31;
        shl.b64         %rd47, %rd47, 32;
        or.b64          %rd46, %rd46, %rd47;
        mov.b64         %fd31, %rd46;
        add.f64         %fd1, %fd1, %fd31;
        // offset 8
        mov.b64         %rd40, %fd0;
        cvt.u32.u64     %r24, %rd40;
        shr.u64         %rd41, %rd40, 32;
        cvt.u32.u64     %r25, %rd41;
         shfl.sync.down.b32  %r26, %r24, 8, 31, 0xffffffff;
         shfl.sync.down.b32  %r27, %r25, 8, 31, 0xffffffff;
        cvt.u64.u32     %rd42, %r26;
        cvt.u64.u32     %rd43, %r27;
        shl.b64         %rd43, %rd43, 32;
        or.b64          %rd42, %rd42, %rd43;
        mov.b64         %fd30, %rd42;
        add.f64         %fd0, %fd0, %fd30;
        mov.b64         %rd44, %fd1;
        cvt.u32.u64     %r28, %rd44;
        shr.u64         %rd45, %rd44, 32;
        cvt.u32.u64     %r29, %rd45;
         shfl.sync.down.b32  %r30, %r28, 8, 31, 0xffffffff;
         shfl.sync.down.b32  %r31, %r29, 8, 31, 0xffffffff;
        cvt.u64.u32     %rd46, %r30;
        cvt.u64.u32     %rd47, %r31;
        shl.b64         %rd47, %rd47, 32;
        or.b64          %rd46, %rd46, %rd47;
        mov.b64         %fd31, %rd46;
        add.f64         %fd1, %fd1, %fd31;
        // offset 4
        mov.b64         %rd40, %fd0;
        cvt.u32.u64     %r24, %rd40;
        shr.u64         %rd41, %rd40, 32;
        cvt.u32.u64     %r25, %rd41;
         shfl.sync.down.b32  %r26, %r24, 4, 31, 0xffffffff;
         shfl.sync.down.b32  %r27, %r25, 4, 31, 0xffffffff;
        cvt.u64.u32     %rd42, %r26;
        cvt.u64.u32     %rd43, %r27;
        shl.b64         %rd43, %rd43, 32;
        or.b64          %rd42, %rd42, %rd43;
        mov.b64         %fd30, %rd42;
        add.f64         %fd0, %fd0, %fd30;
        mov.b64         %rd44, %fd1;
        cvt.u32.u64     %r28, %rd44;
        shr.u64         %rd45, %rd44, 32;
        cvt.u32.u64     %r29, %rd45;
         shfl.sync.down.b32  %r30, %r28, 4, 31, 0xffffffff;
         shfl.sync.down.b32  %r31, %r29, 4, 31, 0xffffffff;
        cvt.u64.u32     %rd46, %r30;
        cvt.u64.u32     %rd47, %r31;
        shl.b64         %rd47, %rd47, 32;
        or.b64          %rd46, %rd46, %rd47;
        mov.b64         %fd31, %rd46;
        add.f64         %fd1, %fd1, %fd31;
        // offset 2
        mov.b64         %rd40, %fd0;
        cvt.u32.u64     %r24, %rd40;
        shr.u64         %rd41, %rd40, 32;
        cvt.u32.u64     %r25, %rd41;
         shfl.sync.down.b32  %r26, %r24, 2, 31, 0xffffffff;
         shfl.sync.down.b32  %r27, %r25, 2, 31, 0xffffffff;
        cvt.u64.u32     %rd42, %r26;
        cvt.u64.u32     %rd43, %r27;
        shl.b64         %rd43, %rd43, 32;
        or.b64          %rd42, %rd42, %rd43;
        mov.b64         %fd30, %rd42;
        add.f64         %fd0, %fd0, %fd30;
        mov.b64         %rd44, %fd1;
        cvt.u32.u64     %r28, %rd44;
        shr.u64         %rd45, %rd44, 32;
        cvt.u32.u64     %r29, %rd45;
         shfl.sync.down.b32  %r30, %r28, 2, 31, 0xffffffff;
         shfl.sync.down.b32  %r31, %r29, 2, 31, 0xffffffff;
        cvt.u64.u32     %rd46, %r30;
        cvt.u64.u32     %rd47, %r31;
        shl.b64         %rd47, %rd47, 32;
        or.b64          %rd46, %rd46, %rd47;
        mov.b64         %fd31, %rd46;
        add.f64         %fd1, %fd1, %fd31;
        // offset 1
        mov.b64         %rd40, %fd0;
        cvt.u32.u64     %r24, %rd40;
        shr.u64         %rd41, %rd40, 32;
        cvt.u32.u64     %r25, %rd41;
         shfl.sync.down.b32  %r26, %r24, 1, 31, 0xffffffff;
         shfl.sync.down.b32  %r27, %r25, 1, 31, 0xffffffff;
        cvt.u64.u32     %rd42, %r26;
        cvt.u64.u32     %rd43, %r27;
        shl.b64         %rd43, %rd43, 32;
        or.b64          %rd42, %rd42, %rd43;
        mov.b64         %fd30, %rd42;
        add.f64         %fd0, %fd0, %fd30;
        mov.b64         %rd44, %fd1;
        cvt.u32.u64     %r28, %rd44;
        shr.u64         %rd45, %rd44, 32;
        cvt.u32.u64     %r29, %rd45;
         shfl.sync.down.b32  %r30, %r28, 1, 31, 0xffffffff;
         shfl.sync.down.b32  %r31, %r29, 1, 31, 0xffffffff;
        cvt.u64.u32     %rd46, %r30;
        cvt.u64.u32     %rd47, %r31;
        shl.b64         %rd47, %rd47, 32;
        or.b64          %rd46, %rd46, %rd47;
        mov.b64         %fd31, %rd46;
        add.f64         %fd1, %fd1, %fd31;
        // lane 0 computes mean/invstd and stores
        setp.eq.u32     %p2, %r22, 0;
        @!%p2 bra       L_after_final_warp_reduce;
            cvt.rn.f64.u32 %fd10, %r20;
            div.rn.f64      %fd11, %fd0, %fd10;
            div.rn.f64      %fd13, %fd1, %fd10;
            mul.f64         %fd14, %fd11, %fd11;
            sub.f64         %fd19, %fd13, %fd14;
            max.f64         %fd19, %fd19, 0d0000000000000000;
            cvt.f64.f32     %fd20, %f20;
            add.f64         %fd15, %fd19, %fd20;
            sqrt.rn.f64     %fd16, %fd15;
            rcp.rn.f64      %fd17, %fd16;
            cvt.rn.f32.f64  %f11, %fd11;
            cvt.rn.f32.f64  %f17, %fd17;
            st.shared.f32   [sh_mean], %f11;
            st.shared.f32   [sh_invstd], %f17;
L_after_final_warp_reduce:
    bar.sync 0;
    // Load mean and invstd for all threads
    // Load mean and invstd for all threads
    ld.shared.f32   %f30, [sh_mean];
    ld.shared.f32   %f31, [sh_invstd];
    // ------------------------------------------------------------
    // Final phase: normalize and apply affine
    // ------------------------------------------------------------
    // Vectorized normalize+affine: 4 elements per iteration, unrolled by 2
    mov.u32         %r4, %r0;                  // vec_idx = tid
    shr.u32         %r5, %r20, 2;              // N4 = N / 4
L_loop_norm_vec:
    setp.ge.u32     %p3, %r4, %r5;
    @%p3 bra        L_done_norm_vec;
    // first vector
    mul.wide.u32    %rd36, %r4, 16;            // byte offset = vec_idx * 16
    add.s64         %rd40, %rd30, %rd36;       // in addr
    add.s64         %rd41, %rd31, %rd36;       // out addr
    add.s64         %rd42, %rd12, %rd36;       // gamma addr
    add.s64         %rd43, %rd13, %rd36;       // beta addr
    ld.global.v4.f32 {%f2,%f3,%f4,%f5}, [%rd40];   // x4
    ld.global.v4.f32 {%f6,%f7,%f8,%f9}, [%rd42];   // gamma4
    ld.global.v4.f32 {%f10,%f11,%f12,%f13}, [%rd43]; // beta4
    // y = ((x - mean) * invstd) * gamma + beta
    sub.f32         %f14, %f2, %f30;
    sub.f32         %f15, %f3, %f30;
    sub.f32         %f16, %f4, %f30;
    sub.f32         %f17, %f5, %f30;
    mul.f32         %f14, %f14, %f31;
    mul.f32         %f15, %f15, %f31;
    mul.f32         %f16, %f16, %f31;
    mul.f32         %f17, %f17, %f31;
    mul.f32         %f14, %f14, %f6;
    mul.f32         %f15, %f15, %f7;
